/** Agent frontmatter `category` to skill card category. */
export const AGENT_CATEGORY_TO_SKILL: Record<string, string> = {
  backend: "backend",
  frontend: "frontend",
  design: "frontend",
  llm: "ai",
  security: "security",
  testing: "testing",
  devops: "devops",
  product: "product",
  research: "research",
  data: "data",
  git: "development",
};

export const AGENT_WEIGHT = 2;

const AGENT_CATEGORY: Record<string, string> = Object.fromEntries(
  AGENTS.map((a) => [a.name, a.category]),
);

function tagMatches(tag: string, keyword: string): boolean {
  return tag === keyword || tag.split(/[-_.]/).includes(keyword);
}

export function categorizeSkill(
  skill: Pick<SkillMeta, "tags" | "agent">,
  agentCategory: Record<string, string> = AGENT_CATEGORY,
): string {
  const tags = skill.tags.map((t) => t.toLowerCase());
  const owner = skill.agent
    ? AGENT_CATEGORY_TO_SKILL[agentCategory[skill.agent] ?? ""]
    : undefined;

  let best = "development";
  let bestScore = 0;
  for (const [category, keywords] of Object.entries(TAG_CATEGORY_MAP)) {
    let score = tags.filter((tag) =>
      keywords.some((k) => tagMatches(tag, k)),
    ).length;
    if (category === owner) score += AGENT_WEIGHT;
    const winsTie = score === bestScore && score > 0 && category === owner;
    if (score > bestScore || winsTie) {
      best = category;
      bestScore = score;
    }
  }
  // An owner outside the tag map (git) still beats the bare fallback.
  if (bestScore === 0 && owner) return owner;
  return best;
}
